database_endpoint &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="s2"&gt;"postgres-db.cspuccciib8v.us-east-1.rds.amazonaws.com:5432"&lt;/span&gt;
ec2_first_instance_ip_address &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="s2"&gt;"3.222.64.160"&lt;/span&gt;
ec2_second_instance_ip_address &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="s2"&gt;"3.223.185.158"&lt;/span&gt;
